struct Vec2 {
    float x;
    float y;
};

Vec2 add(Vec2 a, Vec2 b) {
    return {a.x + b.x, a.y + b.y};
}

Vec2 pos{1.0f, 2.0f};
Vec2 vel{0.5f, -1.0f};
pos = add(pos, vel);       // 位置 += 速度
std::cout << pos.x << ", " << pos.y << '\n';

struct Player {
    int hp;
    int score;
};

void damageByValue(Player p, int d) { p.hp -= d; }  // コピーを変更

void damage(Player& p, int d) {                      // 元を変更
    p.hp -= d;
    if (p.hp < 0) p.hp = 0;
}

void show(const Player& p) {                         // 読むだけ
    std::cout << "HP: " << p.hp << '\n';
}

Player pl{100, 0};
damageByValue(pl, 30);
show(pl);
damage(pl, 30);
show(pl);
damage(pl, 200);
show(pl);

struct Rect {
    float x, y, w, h;   // 左上の座標と、幅、高さ
};

bool hit(const Rect& a, const Rect& b) {
    return a.x < b.x + b.w && a.x + a.w > b.x &&
           a.y < b.y + b.h && a.y + a.h > b.y;
}

Rect player{0, 0, 2, 2};
Rect enemy{1, 1, 2, 2};
Rect wall{5, 5, 1, 1};

std::cout << hit(player, enemy) << ' ' << hit(player, wall) << '\n';

