struct Enemy { std::string name; int hp; };

std::vector<Enemy> enemies = {{"Slime", 20}, {"Bat", 0}, {"Goblin", 35}};

// HP が 0 以下の敵を取り除く
enemies.erase(
    std::remove_if(enemies.begin(), enemies.end(),
                   [](const Enemy& e) { return e.hp <= 0; }),
    enemies.end());

// HP の高い順に並べる
std::sort(enemies.begin(), enemies.end(),
          [](const Enemy& a, const Enemy& b) { return a.hp > b.hp; });

for (const auto& e : enemies) std::cout << e.name << ' ';

class Player {
public:
    Player(const std::string& name, int maxHp)
        : name_(name), hp_(maxHp), maxHp_(maxHp) {}

    void takeDamage(int d) { hp_ -= d; if (hp_ < 0) hp_ = 0; }
    void heal(int v)       { hp_ += v; if (hp_ > maxHp_) hp_ = maxHp_; }
    bool isAlive() const   { return hp_ > 0; }
    int hp() const         { return hp_; }
    const std::string& name() const { return name_; }

private:
    std::string name_;
    int hp_;
    int maxHp_;
};

Player hero("Hero", 100);
hero.takeDamage(70);
std::cout << hero.hp() << '\n';
hero.heal(50);
std::cout << hero.hp() << '\n';
hero.takeDamage(200);
std::cout << hero.hp() << ' ' << hero.isAlive() << '\n';

class Entity {
public:
    virtual ~Entity() = default;
    virtual void update() = 0;   // 派生クラスで必ず実装する
};

class Slime : public Entity {
public:
    void update() override { std::cout << "Slime: ぴょんぴょん\n"; }
};

class Bat : public Entity {
public:
    void update() override { std::cout << "Bat: 飛び回る\n"; }
};

std::vector<std::unique_ptr<Entity>> world;
world.push_back(std::make_unique<Slime>());
world.push_back(std::make_unique<Bat>());

for (auto& e : world) {
    e->update();
}

